    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # BFS with Dijkstra's algorithm (since weights are non-negative)
    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n
    queue = deque()

    queue.append(s)
    visited[s] = True

    while queue:
        u = queue.popleft()
        for v, w in adj[u]:
            if not visited[v]:
                dist[v] = dist[u] + w
                visited[v] = True
                queue.append(v)
            else:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    queue.append(v)

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
