def solve(n, edges, s, t):
    from collections import deque

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to find shortest paths from s to all other nodes
    # Initialize distances to infinity
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == INF:
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check if t is reachable
    if dist[t] == INF:
        return -1
    else:
        return dist[t]
