from collections import deque

def solve(n, edges, s, t):
    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Dijkstra's algorithm to find shortest path from s to t
    if s == t:
        return 0

    dist = [float('inf')] * n
    dist[s] = 0
    visited = [False] * n
    pq = deque()
    pq.append((0, s))  # (distance, node)

    while pq:
        curr_dist, u = pq.popleft()

        if visited[u]:
            continue

        visited[u] = True

        for v, weight in graph[u]:
            if not visited[v]:
                new_dist = curr_dist + weight
                if new_dist < dist[v]:
                    dist[v] = new_dist
                    pq.append((new_dist, v))

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
